#include <lmcpp/lmcpp.hpp>
#include <algorithm>
#include <fstream>
#include <iostream>
#include <filesystem>
#include <set>
#include <sstream>
using namespace lmcpp;
static Json load(const std::string&p){std::ifstream f(p);if(!f)throw std::runtime_error("cannot open "+p);return Json::parse(f);}
static Type type_of(const std::string&t){if(t=="number")return Type::Number;if(t=="integer")return Type::Integer;if(t=="boolean")return Type::Boolean;if(t=="object")return Type::Object;if(t=="array")return Type::Array;if(t=="json")return Type::Json;return Type::String;}
static Operation operation_of(const Json&s){Operation o;o.name=s.value("name","op");if(s.contains("params"))for(const auto&j:s["params"]){Param p;p.name=j.value("name","");p.type=type_of(j.value("type","string"));p.occurs=j.value("occurs","1");p.default_value=j.value("default",Json());p.positional=j.value("positional",false);p.cli_only=j.value("cliOnly",false);p.doc_only=j.value("docOnly",false);if(j.contains("enum"))p.enum_values=j["enum"].get<std::vector<Json>>();if(j.contains("aliases"))p.aliases=j["aliases"].get<std::vector<std::string>>();if(j.contains("items"))p.item_type=type_of(j["items"].get<std::string>());o.params.push_back(p);}return o;}
static std::vector<Param> globals_of(const Json&d){std::vector<Param> r;if(d.contains("globals"))for(auto&g:d["globals"]){Param p;p.name=g.value("name","");p.type=type_of(g.value("type","string"));p.occurs=g.value("occurs","1");if(g.contains("aliases"))p.aliases=g["aliases"].get<std::vector<std::string>>();r.push_back(p);}return r;}
static bool same_issue(const Json&got,const Json&want){if(got.value("code","")!=want.value("code",""))return false;for(auto k:{"param","op"})if(want.contains(k)&&got.value(k,Json())!=want[k])return false;return true;}
static bool errors_match(const Json&got,const Json&want){if(!got.is_array()||!want.is_array()||got.size()!=want.size())return false;for(size_t i=0;i<got.size();++i)if(!same_issue(got[i],want[i]))return false;return true;}
static Json cli_error_issues(const Json&got){if(got.contains("error")&&got["error"].contains("data")&&got["error"]["data"].contains("issues"))return got["error"]["data"]["issues"];return Json::array();}
static bool cli_validate_case(const Json&c){const Json&ex=c["expect"];std::string form=c.value("form","flags");if(form=="graphql")return true;Operation op=operation_of(c["schema"]);CliSpec spec{"fixture","1",{}};op.handler=[](const Params&p){return p;};spec.operations.push_back(op);std::vector<std::string>args{op.name};Json input=c.value("input",Json::object());if(form=="json"){args.push_back("--input-json");args.push_back(input.dump());}else if(input.is_object()){bool empty_list=false;for(auto it=input.begin();it!=input.end();++it)empty_list|=it.value().is_array()&&it.value().empty();if(empty_list){args.push_back("--input-json");args.push_back(input.dump());}else for(auto it=input.begin();it!=input.end();++it){std::string name=it.key();std::replace(name.begin(),name.end(),'_','-');bool boolean_param=false;for(const auto&p:op.params)if(p.name==it.key())boolean_param=p.type==Type::Boolean;auto emit=[&](const Json&v){if(v.is_boolean())args.push_back("--"+name+(v.get<bool>()?"=true":"=false"));else if(boolean_param)args.push_back("--"+name+"="+(v.is_string()?v.get<std::string>():v.dump()));else{args.push_back("--"+name);args.push_back(v.is_string()?v.get<std::string>():v.dump());}};bool repeated=false;for(const auto&p:op.params)if(p.name==it.key())repeated=p.type!=Type::Array&&(p.occurs=="+"||p.occurs=="*");if(it.value().is_array()&&repeated)for(const auto&v:it.value())emit(v);else emit(it.value());}}std::ostringstream out,err;int code=run_cli_io(spec,args,out,err);try{Json got=Json::parse(out.str());if(ex.value("ok",false))return code==0&&got==ex.value("params",Json::object());return code!=0&&errors_match(cli_error_issues(got),ex["issues"]);}catch(...){return false;}}
static bool cli_argv_case(const Json&c){const Json&ex=c["expect"];Operation op=operation_of(c["schema"]);CliSpec spec{"fixture","1",{}};op.handler=[](const Params&p){return p;};spec.operations.push_back(op);std::vector<std::string>args{op.name};for(const auto&x:c.value("argv",std::vector<std::string>{}))args.push_back(x);std::ostringstream out,err;int code=run_cli_io(spec,args,out,err);try{Json got=Json::parse(out.str());if(ex.value("ok",false))return code==0&&got==ex.value("params",Json::object());if(code==0||!got.contains("error"))return false;return got["error"]["data"].contains("issues")&&errors_match(got["error"]["data"]["issues"],ex["issues"]);}catch(...){return false;}}
int main(int argc,char**argv){if(argc!=2){std::cerr<<"usage: conformance <lmapi/conformance>\n";return 2;}if(!std::filesystem::is_directory(argv[1])){std::cerr<<"missing lmapi conformance directory: "<<argv[1]<<"\n";return 2;}int total_fail=0;for(const std::string group:{"validate","argv","publish"}){int pass=0,fail=0,skip=0;for(auto&entry:std::filesystem::directory_iterator(std::string(argv[1])+"/"+group)){if(entry.path().extension()!=".json")continue;Json vectors=load(entry.path().string());for(const auto&c:vectors["cases"]){const Json&ex=c["expect"];try{if(group=="validate"){std::string form=c.value("form","flags");if(form=="graphql"){++skip;continue;}auto op=operation_of(c["schema"]);try{auto got=validate_params(op,c.value("input",Json::object()),form);if(ex.value("ok",false)&&got==ex.value("params",Json::object()))++pass;else {++fail;std::cerr<<group<<" FAIL "<<c["name"]<<" got="<<got.dump()<<" expected="<<ex.dump()<<"\n";}}catch(const Error&e){if(!ex.value("ok",true)&&e.data.contains("issues")&&errors_match(e.data["issues"],ex["issues"]))++pass;else {++fail;std::cerr<<group<<" FAIL "<<c["name"]<<"\n";}}}
else if(group=="argv"){auto op=operation_of(c["schema"]);auto gl=globals_of(c);try{Json got=parse_argv(op,c.value("argv",std::vector<std::string>{}),gl);if(ex.value("ok",false)&&got==Json{{"params",ex.value("params",Json::object())},{"positionals",ex.value("positionals",Json::array())},{"globals",ex.value("globals",Json::object())}})++pass;else {++fail;std::cerr<<group<<" FAIL "<<c["name"]<<" got="<<got.dump()<<" expected="<<ex.dump()<<"\n";}}catch(const Error&e){if(!ex.value("ok",true)&&e.data.contains("issues")&&errors_match(e.data["issues"],ex["issues"]))++pass;else {++fail;std::cerr<<group<<" FAIL "<<c["name"]<<" issues="<<e.data.value("issues",Json::array()).dump()<<" expected="<<ex.dump()<<"\n";}}}
else{Json got=parse_published_schema(c["document"]);if(got.value("ok",false)==ex.value("ok",false)){if(ex.value("ok",false)||errors_match(got["issues"],ex["issues"]))++pass;else {++fail;std::cerr<<group<<" FAIL "<<c["name"]<<"\n";}}else {++fail;std::cerr<<group<<" FAIL "<<c["name"]<<"\n";}}}
catch(const std::exception&e){++fail;std::cerr<<group<<" FAIL "<<c["name"]<<": "<<e.what()<<"\n";}catch(...){++fail;std::cerr<<group<<" FAIL "<<c["name"]<<" (unknown)\n";}}}if(group=="validate"){int cp=0,cf=0,cs=0;for(auto&entry:std::filesystem::directory_iterator(std::string(argv[1])+"/validate")){if(entry.path().extension()!=".json")continue;Json vectors=load(entry.path().string());for(const auto&c:vectors["cases"]){if(c.value("form",std::string("flags"))=="graphql"){++cs;continue;}if(cli_validate_case(c))++cp;else{++cf;std::cerr<<"validate CLI FAIL "<<c["name"]<<"\n";}}}std::cout<<"validate_cli: passed="<<cp<<" failed="<<cf<<" skipped="<<cs<<" (GraphQL unsupported)\n";total_fail+=cf;}if(group=="argv"){int cp=0,cf=0;for(auto&entry:std::filesystem::directory_iterator(std::string(argv[1])+"/argv")){if(entry.path().extension()!=".json")continue;Json vectors=load(entry.path().string());for(const auto&c:vectors["cases"]){if(cli_argv_case(c))++cp;else{++cf;std::cerr<<"argv CLI FAIL "<<c["name"]<<"\n";}}}std::cout<<"argv_cli: passed="<<cp<<" failed="<<cf<<" skipped=0\n";total_fail+=cf;}std::cout<<group<<": passed="<<pass<<" failed="<<fail<<" skipped="<<skip<<"\n";total_fail+=fail;}return total_fail?1:0;}
